const NAMES = new Set(TOOL_DEFS.map((t) => t.name));
export function isToolsTool(name) { return NAMES.has(name); }

export function callToolsTool(name, a) {
  a = a || {};
  try {
    if (name === "style_text_unicode") return styleText(a);
    if (name === "count_characters") return countChars(a);
    if (name === "diff_text") return diffText(a);
    if (name === "generate_color_combinations") return combos(a);
    if (name === "generate_upc_barcode") return upc(a);
    if (name === "text_to_diagram") return diagram(a);
    if (name === "generate_logo_concepts") return logos(a);
    if (name === "passport_photo_size") return passport(a);
  } catch (e) {
    return err("The tool failed: " + (e && e.message ? e.message : String(e)));
  }
  return err("Unknown tool: " + name);
}

function styleText(a) {
  const text = str(a.text, 500);
  if (!text.trim()) return err("Pass some text to style.");
  const opt = {};
  if (a.platform) opt.platform = a.platform;
  if (Array.isArray(a.styles) && a.styles.length) opt.keys = a.styles.map((s) => String(s));
  const rows = MGDUnicodeFonts.all(text, opt);
  if (!rows.length) return err("No styles matched. Omit 'styles' to see all, or try another platform.");
  const lines = rows.map((r) => {
    const bad = Object.entries(r.compat).filter(([, v]) => v !== "ok").map(([k, v]) => `${k}: ${v}`);
    return `- **${r.name}** (\`${r.key}\`): ${r.text}` + (bad.length ? `  _(${bad.join(", ")})_` : "");
  });
  return ok(`${rows.length} Unicode styles for "${text}"${a.platform ? " that display on " + a.platform : ""} — copy any line's text:\n\n` + lines.join("\n") +
    `\n\nMore styles, decorations and real-font PNG/SVG downloads: ${T}/font-generator/ · Instagram bio preview: ${T}/instagram-fonts/ · Discord formatting: ${T}/discord-font-generator/`);
}

function countChars(a) {
  const text = str(a.text, 100000);
  const s = MGDCharCount.stats(text), sms = MGDCharCount.sms(text), x = MGDCharCount.xLength(text);
  const rows = [["Characters", s.characters], ["Characters (no spaces)", s.charactersNoSpaces], ["Words", s.words], ["Sentences", s.sentences],
    ["Paragraphs", s.paragraphs], ["Lines", s.lines], ["Bytes (UTF-8)", s.bytesUtf8], ["Emoji", s.emojis],
    ["Reading time", s.readingTime || (s.readingSeconds != null ? s.readingSeconds + " s" : "")], ["Speaking time", s.speakingTime || (s.speakingSeconds != null ? s.speakingSeconds + " s" : "")]]
    .filter((r) => r[1] !== undefined && r[1] !== "");
  const lim = MGDCharCount.checkAll(text).map((l) => `| ${l.name} | ${l.used} / ${l.limit} | ${l.over ? "**over by " + (l.used - l.limit) + "**" : l.remaining + " left"} |`);
  let out = `| Measure | Value |\n|---|---|\n${rows.map((r) => `| ${r[0]} | ${r[1]} |`).join("\n")}\n\n` +
    `X (Twitter) weighted length: ${x} / 280. SMS: ${sms.encoding}, ${sms.segments} segment(s)` + (sms.nonGsm && sms.nonGsm.length ? ` (UCS-2 forced by: ${sms.nonGsm.slice(0, 10).join(" ")})` : "") + ".\n\n" +
    `| Platform limit | Used | Status |\n|---|---|---|\n${lim.join("\n")}`;
  const L = parseInt(a.limit, 10);
  if (L > 0) out += `\n\nCustom limit ${L}: ${s.characters > L ? "over by " + (s.characters - L) : (L - s.characters) + " characters left"}.`;
  if (a.keywords) {
    const d = MGDCharCount.density(text) || [];
    const top = (Array.isArray(d) ? d : d.words || []).slice(0, 10).map((k) => `${k.word || k.term || k[0]} (${k.count != null ? k.count : k[1]})`);
    if (top.length) out += `\n\nTop keywords: ${top.join(", ")}.`;
  }
  return ok(out + `\n\nLive counter with progress bars for 26 platforms: ${T}/character-counter/`);
}

function diffText(a) {
  const A = str(a.original, 200000), B = str(a.changed, 200000);
  const ws = ["none", "trailing", "change", "all"].includes(a.ignore_whitespace) ? a.ignore_whitespace : "none";
  const opts = { ignoreCase: !!a.ignore_case, ignoreWhitespace: ws, ignoreBlankLines: !!a.ignore_blank_lines };
  const r = MGDDiff.compare(A, B, opts), st = r.stats;
  if (st.identical) return ok(`The two texts are identical${a.ignore_case || ws !== "none" || a.ignore_blank_lines ? " (with the ignore options chosen)" : ""}.`);
  let patch = MGDDiff.unified(A, B, opts);
  if (patch.length > 60000) patch = patch.slice(0, 60000) + "\n… (truncated)";
  return ok(`Changes: ${st.added} line(s) added, ${st.removed} removed, ${st.changed} changed, ${st.unchanged} unchanged — ${st.similarity}% similar, ${st.hunks} change block(s).\n\n\`\`\`diff\n${patch}\n\`\`\`\n\nSide-by-side view with word/character highlights and merge: ${T}/diff-checker/`);
}

function comboText(an, i) {
  const cols = an.colors.map((c) => `${c.name} \`${c.hex.toUpperCase()}\``).join(" + ");
  const pairs = an.pairs.map((p) => `${an.colors[p.a].hex.toUpperCase()}/${an.colors[p.b].hex.toUpperCase()} ${p.ratio}:1 ${p.level}`).join("; ");
  const best = an.best ? ` Best text pairing: ${an.colors[an.best.fg].hex.toUpperCase()} on ${an.colors[an.best.bg].hex.toUpperCase()} (${an.best.ratio}:1).` : "";
  return `${i != null ? i + 1 + ". " : ""}**${cols}** — ${an.harmonyLabel || an.harmony}. Contrast: ${pairs}.${best}\n   Edit: ${T}/color-combination-generator/#c=${an.colors.map((c) => c.hex.slice(1)).join("-")}`;
}
function combos(a) {
  if (Array.isArray(a.analyze) && a.analyze.length) {
    const hexes = a.analyze.slice(0, 3).map((h) => String(h).trim()).map((h) => (h[0] === "#" ? h : "#" + h).toLowerCase());
    if (hexes.length < 2 || hexes.some((h) => !/^#[0-9a-f]{6}$/.test(h))) return err("analyze needs 2–3 six-digit hex colours, e.g. ['#1f2a44', '#ff6f61'].");
    return ok(comboText(MGDCombos.analyze(hexes)));
  }
  const n = int(a.how_many, 4, 1, 8), count = Number(a.colors_per_combination) === 3 ? 3 : 2;
  if (a.base_color && !/^#?[0-9a-f]{6}$/i.test(String(a.base_color).trim())) return err("base_color must be a hex code such as #1f2a44.");
  const base = a.base_color ? "#" + String(a.base_color).trim().replace(/^#/, "") : undefined;
  const seed0 = Math.floor(Math.random() * 1e9), out = [];
  for (let i = 0; i < n; i++) {
    const g = MGDCombos.generate({ count, harmony: a.harmony, base, seed: seed0 + i * 7919 });
    out.push(comboText(MGDCombos.analyze(g.colors), i));
  }
  return ok(`${n} colour combination(s)${a.harmony ? " (" + a.harmony + ")" : ""}${base ? " from " + base.toUpperCase() : ""}:\n\n` + out.join("\n") +
    `\n\nPreview on a business card, poster and website and export CSS/Tailwind: ${T}/color-combination-generator/`);
}

function upc(a) {
  const type = ["upca", "upce", "ean13", "isbn"].includes(a.type) ? a.type : "upca";
  const mag = Math.max(0.8, Math.min(2, Number(a.magnification) || 1));
  const addon = a.addon ? str(a.addon, 5).replace(/\D/g, "") : "";
  if (addon && !/^(\d{2}|\d{5})$/.test(addon)) return err("addon must be 2 or 5 digits.");
  const r = MGDUpc.make(type, str(a.number, 20) + (addon ? " " + addon : ""), { mag });
  if (!r || !r.ok) return err((r && r.error) || "That number isn't valid for " + type.toUpperCase() + ".");
  const rel = Object.entries(r.related || {}).filter(([, v]) => v).map(([k, v]) => `${k.toUpperCase()}: ${v}`).join(" · ");
  return ok(`${type.toUpperCase()} ${r.code}${r.addon ? " + add-on " + r.addon : ""} — ${r.widthMm.toFixed(1)} × ${r.heightMm.toFixed(1)} mm at ${Math.round(mag * 100)}%.` +
    (rel ? `\nRelated codes: ${rel}` : "") + `\n\n\`\`\`svg\n${r.svg}\n\`\`\`\n\nPNG at 300–1200 DPI, EPS, PDF and batch ZIP: ${T}/upc-generator/\nReal retail UPCs must be licensed from GS1 (gs1.org).`);
}

function diagram(a) {
  const text = str(a.text, 20000);
  if (!text.trim()) return err("Pass Mermaid code, arrow lines or an outline.");
  const r = MGDDiagram.textToDiagram({ text, type: a.type || "auto", direction: a.direction, layout: a.layout, transparent: !!a.transparent });
  const n = r.nodes != null ? (Array.isArray(r.nodes) ? r.nodes.length : r.nodes) : (r.model && r.model.nodes ? r.model.nodes.length : null);
  const e = r.edges != null ? (Array.isArray(r.edges) ? r.edges.length : r.edges) : (r.model && r.model.edges ? r.model.edges.length : null);
  const tool = r.type === "mindmap" ? "mind-map-maker" : "flowchart-maker";
  const head = `${r.type === "mindmap" ? "Mind map" : "Flowchart"}: ${n != null ? n + " " + (r.type === "mindmap" ? "topics" : "shapes") : ""}${e != null && r.type !== "mindmap" ? ", " + e + " connectors" : ""}, ${Math.round(r.width)}×${Math.round(r.height)} px.` +
    (r.warnings && r.warnings.length ? `\nNotes: ${r.warnings.join("; ")}` : "");
  return ok(`${head}\n\n\`\`\`svg\n${r.svg}\n\`\`\`\n\nEdit it, restyle it and export PNG/PDF: paste the same text into ${T}/${tool}/ (Text mode).`);
}

function logos(a) {
  const name = str(a.name, 40).trim();
  if (!name) return err("Pass a brand name.");
  const n = int(a.count, 3, 1, 6);
  const styles = MGDLogo.STYLE_NAMES || [];
  const style = styles.includes(a.style) ? a.style : undefined;
  const ind = a.industry ? (MGDLogo.industries || []).find((x) => x.toLowerCase() === String(a.industry).toLowerCase()) : undefined;
  const cs = MGDLogo.concepts({ name, tagline: str(a.tagline, 60), industry: ind, style, count: n, seed: int(a.seed, 0, 0, 1e9) });
  const parts = cs.slice(0, n).map((c, i) => {
    const r = MGDLogo.render(c, { embedFontCss: true });
    const svg = typeof r === "string" ? r : r.svg;
    return `### Concept ${i + 1} — ${c.layout} layout, ${c.style} style\n\n\`\`\`svg\n${svg}\n\`\`\``;
  });
  return ok(`${parts.length} logo concept(s) for "${name}"${ind ? " (" + ind + ")" : ""}:\n\n` + parts.join("\n\n") +
    `\n\nThese SVGs load their fonts from Google Fonts. For outlined SVG (no font dependency), transparent PNG up to 4096 px and a free brand kit (favicons, social sizes, guidelines), open ${T}/logo-maker/ and enter "${name}".` +
    (a.industry && !ind ? `\n(Industry "${a.industry}" not recognised; options: ${(MGDLogo.industries || []).join(", ")}.)` : ""));
}

function specLine(s) {
  const inch = (mm) => (mm / 25.4).toFixed(2).replace(/\.?0+$/, "");
  return `**${s.label}** — print ${s.w} × ${s.h} mm (${inch(s.w)} × ${inch(s.h)} in); digital ${s.px[0]} × ${s.px[1]} px; head height ${s.head[0]}–${s.head[1]} mm` +
    (s.eyes ? `; eyes ${s.eyes[0]}–${s.eyes[1]} mm from the bottom` : "") + `; background ${s.bg}. ${s.note || ""} _Source: ${s.src || "general ICAO guidance"}._`;
}
function passport(a) {
  const S = MGDPassport.SPECS;
  let hits = [];
  if (a.document) hits = S.filter((s) => s.id === a.document);
  else if (a.query) {
    const words = String(a.query).toLowerCase().split(/[^a-z0-9]+/).filter((w) => w && !["photo", "size", "requirements", "for", "the"].includes(w));
    hits = S.filter((s) => words.every((w) => (s.label + " " + s.id).toLowerCase().includes(w)));
    if (!hits.length) hits = S.filter((s) => words.some((w) => (s.label + " " + s.id).toLowerCase().includes(w)));
  }
  const list = hits.length ? hits : S;
  return ok((hits.length ? "" : (a.document || a.query ? "No exact match — all documents:\n\n" : "All documents:\n\n")) + list.map(specLine).join("\n\n") +
    `\n\nMake a compliant photo (head-size guides, background check, 4×6 in / 10×15 cm print sheets): ${T}/passport-photo-maker/\nAlways confirm with the issuing authority before submitting.`);
}
